<?php if ( ! defined( 'ABSPATH' ) ) { exit; } ?><div class="sd-onboarding-step"><span class="sd-eyebrow"><?php esc_html_e( 'Step 3 of 6', 'social-discovery' ); ?></span><h2><?php esc_html_e( 'Add a profile image', 'social-discovery' ); ?></h2><p><?php esc_html_e( 'Profile image uploads use BuddyPress when it is active. You can skip this step and add one later.', 'social-discovery' ); ?></p><div class="sd-onboarding-avatar-preview"><img src="<?php echo esc_url( sd_avatar( get_current_user_id(), 128 ) ); ?>" alt="<?php esc_attr_e( 'Current profile image', 'social-discovery' ); ?>"></div><?php if ( function_exists( 'bp_core_avatar_handle_upload' ) ) : ?><p class="sd-field-help"><?php esc_html_e( 'Use your BuddyPress profile controls to upload or replace your avatar.', 'social-discovery' ); ?></p><?php else : ?><p class="sd-field-help"><?php esc_html_e( 'Avatar upload will be available when BuddyPress is installed.', 'social-discovery' ); ?></p><?php endif; ?></div>
